/**
 * Requires a verified Supabase Bearer identity and queries RevenueCat server-side using los_user_<immutable Supabase UUID>. In every environment, an active Premium entitlement must be explicitly attached to a current access-granting App Store or Play Store subscription; RevenueCat Test Store, promotional, and unrelated subscription state are rejected. The request has no body; client entitlement, premium, receipt, and transaction claims are never accepted.
 * @summary Reconcile the authenticated user's native premium entitlement
 */
export const reconcileNativePremiumResponseAppUserIdRegExp = new RegExp('^los_user_[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$');


export const ReconcileNativePremiumResponse = zod.object({
  "appUserId": zod.string().regex(reconcileNativePremiumResponseAppUserIdRegExp),
  "entitlementId": zod.literal("premium"),
  "provider": zod.literal("revenuecat"),
  "isActive": zod.boolean(),
  "isPremium": zod.boolean().describe('Effective access after preserving any valid Stripe subscription.'),
  "expiresAt": zod.coerce.date().nullish(),
  "verifiedAt": zod.coerce.date(),
  "cacheValidUntil": zod.coerce.date()
})


